const candidate = $('Expand Candidates').item.json;
const response = $json;

let text = response.output_text;
if (!text && Array.isArray(response.output)) {
  const parts = [];
  for (const item of response.output) {
    if (!Array.isArray(item.content)) continue;
    for (const content of item.content) {
      if (typeof content.text === 'string') parts.push(content.text);
    }
  }
  text = parts.join('\n');
}

if (!text) {
  return [{ json: { id: candidate.id, failed: true, error_message: 'empty AI response' } }];
}

try {
  const cleaned = String(text).replace(/^\s*```json\s*/i,'').replace(/\s*```\s*$/,'');
  const a = JSON.parse(cleaned);
  const relevance = Math.max(0, Math.min(100, Number(a.relevance_score) || 0));
  const confidence = Math.max(0, Math.min(100, Number(a.confidence_score) || 0));
  const recommendation = relevance >= 85 ? 'HIGH' : relevance >= 70 ? 'REVIEW' : relevance >= 50 ? 'LOW' : 'SKIP';

  let recent = false;
  if (candidate.published_at) {
    recent = Date.now() - new Date(candidate.published_at).getTime() <= 48 * 60 * 60 * 1000;
  }

  return [{
    json: {
      id: candidate.id,
      title_ko: String(a.title_ko || '').slice(0,180),
      summary_ko: String(a.summary_ko || '').slice(0,1200),
      why_it_matters: String(a.why_it_matters || '').slice(0,1200),
      category: ['MODEL','PRODUCT','WORK','AUTOMATION','BUILD','EDUCATION','OTHER'].includes(a.category) ? a.category : 'OTHER',
      relevance_score: relevance,
      confidence_score: confidence,
      recommendation,
      featured_recommended: relevance >= 85 && confidence >= 90 && Number(candidate.trust_score) >= 95 && recent,
      status: relevance >= 50 ? 'review' : 'rejected',
      processed_at: new Date().toISOString(),
      error_message: null,
      failed: false
    }
  }];
} catch (error) {
  return [{ json: { id: candidate.id, failed: true, error_message: 'AI JSON parse failed: ' + error.message } }];
}
